; >S:CHANGE-ROOM; PUT "CHANGE-ROOM";; ALL THE STUFF RELATED WITH; MOVING TO ANOTHER ROOM.;CHGROM;; CHECK BUFFER 'BEHIND' TO SEE; IF THERE IS A DOOR THERE.;LDY #0LDX #3;CLK;LDA BEHIND,XCMP #200      ;* DOOR CHARBNE NXT;INY;NXT;DEXBPL CLK;CPY #2BEQ NEWBOD;RTS;NEWBOD;; THERE WERE TWO DOOR CHARS SO; HE MUST BE RIGHT NEXT TO A DOOR; BY LOOKING AT THE VALUE OF;; 'DIR' 0-LEFT 1-RIGHT 2-UP 4-DOWN;; IT IS KNOWN WHICH WAY HE HAS; MOVED;LDA #1STA NEWROM ;* TELL BASIC LOOPSTA STOP   ;* TO CHANGE TO NEW;          ;* ROOM;RTS;;-------------------------------;; CALLED BY THE BASIC LOOP; TO MOVE TO A NEW ROOM - THE; BASIC LOOP HAS CONTROL.;ROOMON;;LDA #1;STA STOP    ;* HALT EVERYTHING;; WILL ALREADY HAVE BEEN DONE;LDA #1BIT DIRBNE SCRLFT  ;* GOING LEFT;ASL ABIT DIRBNE SCRRGT  ;* GOING RIGHT;ASL ABIT DIRBNE SCRUP   ;* GOING UP;ASL ABIT DIRBNE SCRDWN;RTS;;----------;SCRRGT;INC XPOS;LDA #0STA MANXLDA #11STA MANY;JMP JMPBAK;;************;SCRLFT;DEC XPOS;LDA #28STA MANXLDA #11STA MANY;JMP JMPBAK;;************;SCRDWN;INC YPOS;LDA #15STA MANXLDA #0STA MANY;JMP JMPBAK;;**********;SCRUP;DEC YPOS;LDA #15STA MANXLDA #20STA MANY;; JMP JMPBAK;JMPBAK;; ALL THE ABOVE ROUTINES MUST; JUMP BACK HERE TO CONTINUE;LDY YPOSLDA TIME5,YCLCADC XPOSSTA SCREEN ;* 0 - 24;TAXLDA GOTBIT,X ;* CLEARED THIS ROOM?STA CLEARD   ;* 0 = NO;JSR SETLVL   ;* SET LEVEL VARS;LDX #0STX PRTALSSTX NEWROMSTX GOINGSTX XPIXSTX YPIXSTX BOMBON ;* KILL THE BOMB IFSTX BOMBGO ;* CHANGING ROOMS;; JSR INITAL ;* START NEW ALIENS;JSR DECODE ;* PUT NEW SCREEN ON;LDA #$10STA DELLY  ;* DELAY FOR FADE IN;JSR FADEIN ;* COPY IT ONTO SCREEN;LDA CLEARDBNE TENSON;; PRINT JIG-PIECE IF ROOM NOT; CLEARED YET;JSR PRPICE ;* PRINT JIGSW PIECE;JMP DRINK;TENSON;JSR GOTMES ;* PRINT MESS IF DONE;LDA #7STA ALMVET;DRINK;LDA MANXSTA SAVEX;LDA MANYSTA SAVEY;LDA DIRSTA SAVDIR;LDA #14STA CHKX;LDA #10STA CHKY;LDA DUCKBNE FRUT;JSR INITKL  ;* NUMBER TO KILL;FRUT;; JSR SETLVL  ;* SET LEVEL VALS;JSR INITAL  ;* START ALIENS;LDA #0STA STOP;RTS     ;* RETURN TO BASIC 'LOOP';;---------------------------;;;.END